import os,json,subprocess,pathlib,time,concurrent.futures,hashlib
B=pathlib.Path('/tmp/cohort-manifest-validation-private');B.mkdir(exist_ok=True)
BIN='/tmp/entire-brain-manifest-candidate';ROWS=json.load(open('/tmp/cohort-selected-private.json'))
def run(r):
 ident=r['opaque_id'];root=B/ident;root.mkdir(exist_ok=True);env=dict(os.environ,ENTIRE_REPO_ROOT=r['path'],ENTIRE_BRAIN_NO_EGRESS='1',ENTIRE_BRAIN_LOCAL_ONLY='1',GIT_NO_LAZY_FETCH='1');summary={'id':ident,'before_bytes':os.path.getsize(r['manifest']),'commands':{}}
 def cmd(name,args,timeout=1800):
  start=time.monotonic()
  with open(root/(name+'.out'),'w') as out,open(root/(name+'.err'),'w') as err:
   try:rc=subprocess.run([BIN]+args,cwd=r['path'],env=env,stdout=out,stderr=err,timeout=timeout).returncode
   except subprocess.TimeoutExpired:rc='timeout'
  summary['commands'][name]={'exit':rc,'seconds':round(time.monotonic()-start,2)}
  json.dump(summary,open(root/'summary.json','w'))
 for name,args in [('before-status',['status','--json']),('before-doctor',['doctor','--json']),('refresh',['refresh','--agent','none']),('status',['status','--json']),('doctor',['doctor','--json']),('init-agents',['init-agents','--json'])]:cmd(name,args)
 summary['after_bytes']=os.path.getsize(r['manifest']);json.dump(summary,open(root/'summary.json','w'));print(json.dumps(summary),flush=True)
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as ex:list(ex.map(run,ROWS))
