import json,pathlib,collections,os
rows=json.load(open('/tmp/cohort-selected-private.json'))
b1=pathlib.Path('/tmp/cohort-manifest-validation-private');b2=pathlib.Path('/tmp/cohort-manifest-validation-v2-private')
initial={r['opaque_id']:json.load(open(b1/r['opaque_id']/'summary.json')) for r in rows}
final={r['opaque_id']:json.load(open(b2/r['opaque_id']/'summary.json')) for r in rows}
assert all('init-agents' in d['commands'] for d in final.values())
manifest_ok=0;doctor_errors={};warnings={};schemas={};changed=0
for r in rows:
 rid=r['opaque_id'];d=json.load(open(b2/rid/'doctor.out'))
 manifest_ok+=sum(x['name']=='manifest' and x['state']=='ok' for x in d['checks'])
 es=[x['name'] for x in d['checks'] if x['state']=='error']
 if es:doctor_errors[rid]=es
 m=json.load(open(r['manifest']));schemas[rid]=m['schema_version'];ws=[w for w in m.get('warnings',[]) if isinstance(w,str)]
 warnings[rid]={'scope':sum('scope' in w.lower() for w in ws),'pointer':sum('pointer' in w.lower() for w in ws)}
 changed+=len(json.load(open(b2/rid/'init-agents.out')).get('changed_files',[]))
counts=lambda cmd:dict(collections.Counter(d['commands'][cmd]['exit'] for d in final.values()))
out=['# Sanitized manifest cohort validation','', 'Entire tracking remained enabled. Only opaque repository IDs and aggregate findings are reported. No paid inference, watcher installation, checkpoint repair, publication, source reset, or retained-data deletion was performed.','', '## Existing manifests and normal readers','',f'- Initial status opened all 20 existing manifests unchanged; both original oversized manifests were verified before refresh.',f'- Final status exit codes: {counts("status")}. Doctor manifest checks: {manifest_ok}/20 OK. Final schemas: {dict(collections.Counter(schemas.values()))}.',f'- Overall doctor exit codes: {counts("doctor")}; these are separate from manifest loading.',f'- Coordinated candidate init-agents: {counts("init-agents")}; managed files changed: {changed}. The initial pass also succeeded on all 20 with zero changed files.','', '| ID | Original manifest bytes | Final manifest bytes | Schema | Deterministic worktree refresh | Seconds | Status | Doctor manifest | Overall doctor |','|---|---:|---:|---:|---|---:|---|---|---|']
for rid in ['R01','R03','R02']:
 d=final[rid];c=d['commands'];desc='completed' if c['refresh']['exit']==0 else 'blocked by independent input limit' if rid=='R01' else 'failed'
 out.append(f'| {rid} | {initial[rid]["before_bytes"]:,} | {d["after_bytes"]:,} | {schemas[rid]} | {desc} | {c["refresh"]["seconds"]} | pass | pass | exit {c["doctor"]["exit"]} |')
out+=['','## Refresh scope and remaining limitations','', '- Deterministic processing used --agent none and --worktree, local-only/no-egress settings, and an explicitly disabled external embedder.', '- The first pass hit pre-existing dirty-worktree guards on 19 repositories. The two required large Brains and one already-running additional Brain were retried with --worktree. The other 17 full worktree refreshes were skipped once their regression read checks sufficed.', '- R01 completed session export and seed generation but history rebuilding encountered the unchanged 268,435,456-byte canonical-transcript limit (memory_input_too_large). The full refresh therefore remains incomplete; this is not a manifest-loading failure. No workaround that weakens that unrelated limit or truncates retained data was applied.', '- Post-refresh byte counts reflect normal production refresh writes. Support for the original larger inputs was established by opening their unchanged manifests first.','', '## Other doctor findings','']
for rid,errors in doctor_errors.items():out.append(f'- {rid}: '+', '.join(errors)+'.')
if not doctor_errors:out.append('- None at error severity.')
out+=['', '## Checkpoint coverage warnings, separate from manifest failures','',f'- Remaining top-level checkpoint-scope warning entries: {sum(x["scope"] for x in warnings.values())}. Prior cohort baseline: 2,403.',f'- Remaining top-level checkpoint-pointer warning entries: {sum(x["pointer"] for x in warnings.values())}. These counts classify warning entries by category and do not count the duplicated sources.sessions warnings again.','', '| ID | Scope warnings | Pointer warnings |','|---|---:|---:|']
for rid,w in warnings.items():
 if w['scope'] or w['pointer']:out.append(f'| {rid} | {w["scope"]} | {w["pointer"]} |')
out+=['','## Retained-read probe','', '- Both oversized Brains passed explicit-directory status with no Git executable on PATH and an unavailable ambient source root, from outside a repository. Actual source directories were left untouched, so this checks absent ambient source/Git rather than physically hiding the recorded source directory.', '- Real-cohort source code, transcript contents, identities, and raw diagnostics were kept out of the implementation report.','']
pathlib.Path('/tmp/manifest-cohort-sanitized.md').write_text('\n'.join(out))
print(json.dumps({'status':counts('status'),'doctor':counts('doctor'),'manifest_ok':manifest_ok,'init':counts('init-agents'),'guide_changed':changed,'scope_warnings':sum(x['scope'] for x in warnings.values()),'pointer_warnings':sum(x['pointer'] for x in warnings.values()),'doctor_errors':doctor_errors}))
PY","max_output_tokens":1000}));

